package pythonparity

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"testing"
	"unicode/utf8"
)

// goldenPath locates the fixture generated by
// tests/fixtures/generate_python_json_golden.py.
const goldenPath = "../../tests/fixtures/python_json_python_golden.json"

type serializerCase struct {
	Label         string                       `json:"label"`
	FieldAxis     string                       `json:"field_axis"`
	ReachableInGo bool                         `json:"reachable_in_go"`
	WorkUnitIDHex string                       `json:"work_unit_id_hex"`
	SourcesHex    map[string]map[string]string `json:"sources_hex"`
	Serialized    string                       `json:"serialized"`
	SHA256        string                       `json:"sha256"`
}

type goldenFile struct {
	SerializerCases []serializerCase `json:"serializer_cases"`
}

func loadGolden(t *testing.T) goldenFile {
	t.Helper()

	raw, err := os.ReadFile(filepath.Clean(goldenPath))
	if err != nil {
		t.Fatalf("read golden: %v (regenerate with: uv run python "+
			"tests/fixtures/generate_python_json_golden.py)", err)
	}
	var golden goldenFile
	if err := json.Unmarshal(raw, &golden); err != nil {
		t.Fatalf("parse golden: %v", err)
	}
	if len(golden.SerializerCases) == 0 {
		t.Fatal("golden contains no serializer cases")
	}
	return golden
}

// decodeHex turns the fixture's hex back into the original bytes.
//
// The fixture hex-encodes every string because the corpus deliberately
// contains lone surrogates and control characters. Carrying them as literal
// JSON strings would let the transport normalise them -- Go's JSON decoder
// silently replaces a lone surrogate escape with U+FFFD -- which would quietly
// erase the very cases the corpus exists to cover.
func decodeHex(t *testing.T, encoded string) string {
	t.Helper()
	decoded, err := hex.DecodeString(encoded)
	if err != nil {
		t.Fatalf("decode hex %q: %v", encoded, err)
	}
	return string(decoded)
}

func (testCase serializerCase) payload(t *testing.T) map[string]any {
	t.Helper()

	sources := make(map[string]map[string]string, len(testCase.SourcesHex))
	for sourceTypeHex, textsHex := range testCase.SourcesHex {
		texts := make(map[string]string, len(textsHex))
		for sourceIDHex, textHex := range textsHex {
			texts[decodeHex(t, sourceIDHex)] = decodeHex(t, textHex)
		}
		sources[decodeHex(t, sourceTypeHex)] = texts
	}

	return map[string]any{
		"work_unit_id": decodeHex(t, testCase.WorkUnitIDHex),
		"sources":      sources,
	}
}

// TestMarshalPythonJSONMatchesCPython is the parity test proper: for every
// corpus case Go must produce CPython's bytes exactly, and therefore CPython's
// SHA-256.
//
// The hash is compared as well as the bytes, even though it is derived from
// them, because the hash is what actually ships: it becomes
// categorization_input_hash and gates the LLM skip. Asserting it here means the
// failure message names the thing that would cost money.
func TestMarshalPythonJSONMatchesCPython(t *testing.T) {
	golden := loadGolden(t)

	var reachable int
	for _, testCase := range golden.SerializerCases {
		if !testCase.ReachableInGo {
			continue
		}
		reachable++

		t.Run(testCase.Label, func(t *testing.T) {
			encoded, err := MarshalPythonJSON(testCase.payload(t))
			if err != nil {
				t.Fatalf("encode: %v", err)
			}

			if got := string(encoded); got != testCase.Serialized {
				t.Errorf("serialized bytes differ from CPython\n"+
					"  field axis: %s\n  python: %s\n  go:     %s",
					testCase.FieldAxis, testCase.Serialized, got)
			}

			// ensure_ascii=True is a total guarantee, not a per-case one:
			// CPython's output is pure ASCII for EVERY input. Asserting it
			// across the whole corpus catches any non-ASCII leak in one line,
			// including in cases whose expected bytes happen not to exercise
			// the escape path.
			for offset, b := range encoded {
				if b >= 0x80 {
					t.Fatalf("output byte %d is 0x%02x; ensure_ascii output must "+
						"be pure ASCII: %q", offset, b, encoded)
				}
			}

			digest := fmt.Sprintf("%x", sha256.Sum256(encoded))
			if digest != testCase.SHA256 {
				t.Errorf("input_hash differs from CPython: python=%s go=%s\n"+
					"  this is the LLM skip-existing key; a mismatch re-categorizes "+
					"every work unit on every run", testCase.SHA256, digest)
			}
		})
	}

	// A corpus that silently stopped loading cases would pass vacuously. The
	// floor is deliberately well below the current count so that ADDING cases
	// never fails the build, while emptying the fixture does.
	if reachable < 200 {
		t.Errorf("only %d Go-reachable cases ran; the corpus covers 4 field "+
			"positions x ~30 value shapes and should be far larger -- the "+
			"fixture is probably truncated", reachable)
	}
}

// TestPythonOnlyCasesAreDocumentedDivergences covers the cases the two planes
// CANNOT agree on, and pins WHY.
//
// A Python str may hold a lone surrogate; a Go string cannot hold one as valid
// UTF-8. Such a value is unreachable through the ClickHouse path -- Go receives
// bytes, and the driver would have had to mint the surrogate -- but it is
// reachable in Python if the driver decodes with errors="surrogateescape",
// which turns each invalid byte into U+DCxx.
//
// That is the open question recorded in plan section 5d: strict, replace and
// surrogateescape are three different driver policies producing three
// different Python hashes. This test does not guess between them. It pins the
// only thing measured so far -- that these inputs are invalid UTF-8 on the Go
// side and are encoded as U+FFFD -- so that when the policy IS measured, the
// assumption it invalidates is visible and named rather than buried.
func TestPythonOnlyCasesAreDocumentedDivergences(t *testing.T) {
	golden := loadGolden(t)

	var seen int
	for _, testCase := range golden.SerializerCases {
		if testCase.ReachableInGo {
			continue
		}
		seen++

		t.Run(testCase.Label, func(t *testing.T) {
			payload := testCase.payload(t)

			// The reason the planes diverge, asserted rather than narrated:
			// something in this payload is not valid UTF-8 in Go.
			if validUTF8Throughout(payload) {
				t.Fatalf("case is marked python-only but every string is valid "+
					"UTF-8 in Go; either the marking or this test's premise is "+
					"wrong (field axis %s)", testCase.FieldAxis)
			}

			encoded, err := MarshalPythonJSON(payload)
			if err != nil {
				t.Fatalf("encode: %v", err)
			}
			// Go substitutes U+FFFD, so its bytes must NOT match Python's.
			// If they ever do, the substitution assumption has changed and the
			// open question has silently resolved itself -- which is worth a
			// failure, not a pass.
			if string(encoded) == testCase.Serialized {
				t.Errorf("expected a divergence for a lone-surrogate input, but "+
					"Go reproduced CPython exactly: %s", testCase.Serialized)
			}
			// The ESCAPE SEQUENCE -- six ASCII characters -- not a literal
			// U+FFFD. ensure_ascii output never contains a non-ASCII byte, so
			// looking for the literal character here would be looking for the
			// one thing that must never appear.
			if !bytes.Contains(encoded, []byte(`\ufffd`)) {
				t.Errorf("expected each invalid byte to encode as the U+FFFD "+
					"escape sequence; got %s", encoded)
			}
		})
	}

	if seen == 0 {
		t.Error("no python-only cases found; the corpus should contain lone-surrogate " +
			"shapes, and losing them would hide a known divergence")
	}
}

func validUTF8Throughout(payload map[string]any) bool {
	for _, value := range payload {
		switch typed := value.(type) {
		case string:
			if !utf8.ValidString(typed) {
				return false
			}
		case map[string]map[string]string:
			for sourceType, texts := range typed {
				if !utf8.ValidString(sourceType) {
					return false
				}
				for sourceID, text := range texts {
					if !utf8.ValidString(sourceID) || !utf8.ValidString(text) {
						return false
					}
				}
			}
		}
	}
	return true
}

// TestLineSeparatorsAgreeOnlyByCoincidence pins the one row of the divergence
// table where the two planes happen to produce identical output for unrelated
// reasons.
//
// Python escapes U+2028/U+2029 because ensure_ascii escapes everything at or
// above U+007F. Go escapes them because of a hard-coded JavaScript-safety
// carve-out that survives SetEscapeHTML(false) -- Go leaves every OTHER
// non-ASCII code point literal. The agreement is therefore an accident of two
// unrelated rules, and it is pinned here so that it is understood as one.
func TestLineSeparatorsAgreeOnlyByCoincidence(t *testing.T) {
	for _, testCase := range []struct {
		name  string
		value string
		agree bool
	}{
		{name: "line separator U+2028", value: "a b", agree: true},
		{name: "paragraph separator U+2029", value: "a b", agree: true},
		// The control: an ordinary non-ASCII code point, where the same Go
		// setting produces a LITERAL and the planes disagree. If this ever
		// starts agreeing, Go's encoder has changed behaviour underneath us.
		{name: "accented letter is NOT escaped by Go", value: "café", agree: false},
		{name: "emoji is NOT escaped by Go", value: "\U0001f600", agree: false},
	} {
		t.Run(testCase.name, func(t *testing.T) {
			var buffer bytes.Buffer
			encoder := json.NewEncoder(&buffer)
			encoder.SetEscapeHTML(false)
			if err := encoder.Encode(testCase.value); err != nil {
				t.Fatalf("stdlib encode: %v", err)
			}
			stdlib := bytes.TrimRight(buffer.Bytes(), "\n")
			ours := AppendPythonJSONString(nil, testCase.value)

			if agreed := bytes.Equal(stdlib, ours); agreed != testCase.agree {
				t.Errorf("stdlib/python agreement = %v, want %v\n  stdlib: %s\n  ours:   %s",
					agreed, testCase.agree, stdlib, ours)
			}
		})
	}
}

// TestRefusesUnsupportedTypes pins the deliberate refusal. Python's
// `default=str` would stringify an unexpected type and still hand back a hash;
// reproducing that would mean guessing at CPython's repr, and a plausible wrong
// hash is worse than an error, because only one of the two is visible.
func TestRefusesUnsupportedTypes(t *testing.T) {
	for _, testCase := range []struct {
		name  string
		value any
	}{
		{name: "int", value: 1},
		{name: "float", value: 1.5},
		{name: "bool", value: true},
		{name: "nil", value: nil},
		{name: "slice", value: []string{"a"}},
		{name: "nested unsupported", value: map[string]any{"k": 1}},
	} {
		t.Run(testCase.name, func(t *testing.T) {
			if _, err := MarshalPythonJSON(testCase.value); err == nil {
				t.Errorf("expected a refusal for %T, got a silent encoding", testCase.value)
			}
		})
	}
}
